<script setup lang="ts">
import {computed, onMounted, onUnmounted, ref, shallowReactive} from "vue";
import {useAuth} from "@papilio/auth";
import {item, query, request, type ConfigurationDraft, type CoreInstance, type NodeEndpoint, type NodeHealth, type NodeHealthCheck, type NodeQuality, type Page} from "@papilio/api";
import {useI18n} from "vue-i18n";
import {useLocalizedFormats} from "../composables/useLocalizedFormats";
const {t}=useI18n();
const {date:faDate,number:faNumber}=useLocalizedFormats();
const auth=useAuth();
function recordedPage<T>(path:()=>string){
  const state=shallowReactive({rows:[] as T[],page:1,pages:1,total:0,loading:false,error:""});
  let version=0,controller:AbortController|null=null;
  async function load():Promise<void>{
    const current=++version;controller?.abort();controller=new AbortController();const active=controller;state.loading=true;state.error="";
    try{const result=await request<Page<T>>(path(),"GET",undefined,{signal:active.signal});if(current!==version)return;state.rows=result.data;state.pages=result.meta.pager?.total_pages??1;state.total=result.meta.pager?.total_items??0;}
    catch(cause){if(current===version&&!active.signal.aborted)state.error=cause instanceof Error?cause.message:t("testTools.requestFailed");}
    finally{if(current===version)state.loading=false;}
  }
  function reset():void{++version;controller?.abort();state.rows=[];state.page=1;state.pages=1;state.total=0;state.loading=false;state.error="";}
  onUnmounted(reset);return{state,load,reset};
}
const nodeQ=ref(""),coreQ=ref(""),node=ref<NodeEndpoint|null>(null),core=ref<CoreInstance|null>(null),configuration=ref<ConfigurationDraft|null>(null);
const nodes=recordedPage<NodeEndpoint>(():string=>`/v1/admin/network/nodes?${query({q:nodeQ.value,page:nodes.state.page})}`);
const cores=recordedPage<CoreInstance>(():string=>`/v1/admin/network/nodes/${node.value?.id}/cores?${query({q:coreQ.value,page:cores.state.page})}`);
const configurations=recordedPage<ConfigurationDraft>(():string=>`/v1/admin/network/configurations?${query({node_id:node.value?.id,core_id:core.value?.id,page:configurations.state.page})}`);
const health=recordedPage<NodeHealth>(():string=>`/v1/admin/network/health?${query({node_id:node.value?.id,page:health.state.page})}`);
const nodeHealth=computed(()=>health.state.rows.find(row=>row.node_id===node.value?.id)??null);
const source=ref(""),recordedSource=ref(""),quality=ref<NodeQuality[]>([]),qualityLoading=ref(false),qualityError=ref("");
let qualityVersion=0,qualityController:AbortController|null=null,alive=true;
const busy=ref(false),actionError=ref(""),notice=ref("");
async function chooseNode(row:NodeEndpoint):Promise<void>{if(busy.value)return;node.value=row;core.value=null;configuration.value=null;coreQ.value="";cores.reset();configurations.reset();health.reset();actionError.value="";notice.value="";await Promise.all([cores.load(),configurations.load(),health.load()]);}
async function chooseCore(row:CoreInstance|null):Promise<void>{if(busy.value)return;core.value=row;configuration.value=null;configurations.reset();await configurations.load();}
async function loadQuality():Promise<void>{
  if(source.value.trim().length<2)return;const network=source.value.trim(),version=++qualityVersion;qualityController?.abort();const controller=new AbortController();qualityController=controller;qualityLoading.value=true;qualityError.value="";
  try{const result=await request<{data:NodeQuality[]}>(`/v1/admin/network/quality?${query({client_network:network})}`,"GET",undefined,{signal:controller.signal});if(!alive||version!==qualityVersion)return;quality.value=result.data;recordedSource.value=network;}
  catch(cause){if(alive&&version===qualityVersion&&!controller.signal.aborted)qualityError.value=cause instanceof Error?cause.message:t("testTools.measurementsFailed");}
  finally{if(alive&&version===qualityVersion)qualityLoading.value=false;}
}
async function recalculate():Promise<void>{
  const selected=node.value;if(!selected||busy.value||!auth.can("network","manage"))return;busy.value=true;actionError.value="";notice.value="";
  try{await item<NodeHealthCheck>(`/v1/admin/network/health/${selected.id}/check`,"POST");if(!alive)return;notice.value=t("testTools.recalculateNotice");await health.load();}
  catch(cause){if(alive)actionError.value=cause instanceof Error?cause.message:t("testTools.checkFailed");}
  finally{if(alive)busy.value=false;}
}
const healthLabels=computed<Record<string,string>>(()=>({disabled:t("testTools.health.disabled"),unknown:t("testTools.health.unknown"),stale:t("testTools.health.stale"),insufficient:t("testTools.health.insufficient"),healthy:t("testTools.health.healthy"),degraded:t("testTools.health.degraded"),unreachable:t("testTools.health.unreachable")}));
const configurationLink=computed(()=>configuration.value?{path:`/network/${configuration.value.node_id}/cores/${configuration.value.core_id}/configurations`,query:{configuration_id:configuration.value.id}}:null);
onMounted(nodes.load);onUnmounted(()=>{alive=false;++qualityVersion;qualityController?.abort();});
</script>
<template>
  <div class="page-head"><div><p class="eyebrow">{{t("testTools.eyebrow")}}</p><h1>{{t("testTools.title")}}</h1><p class="subtitle">{{t("testTools.subtitle")}}</p></div><RouterLink to="/network" class="btn secondary">{{t("testTools.manageNodes")}}</RouterLink></div>
  <div class="hint-box">{{t("testTools.evidenceHint")}}</div>
  <section class="card card-pad lab-section"><h2>{{t("testTools.chooseNode")}}</h2><form class="toolbar" @submit.prevent="nodes.state.page=1;nodes.load()"><label class="field"><span>{{t("testTools.searchNode")}}</span><input v-model="nodeQ" maxlength="100" :disabled="busy"/></label><button class="btn secondary" :disabled="nodes.state.loading||busy">{{t("testTools.searchNodes")}}</button></form><p v-if="nodes.state.error" class="message error" role="alert">{{nodes.state.error}}</p><p v-if="nodes.state.loading">{{t("testTools.loadingNodes")}}</p><div class="inline-actions"><button v-for="row in nodes.state.rows" :key="row.id" class="btn secondary" :aria-pressed="node?.id===row.id" :disabled="busy" @click="chooseNode(row)">{{row.label}} <span class="badge" :class="row.is_enabled?'success':'warning'">{{row.is_enabled?t("testTools.enabled"):t("testTools.disabled")}}</span></button></div><p v-if="!nodes.state.loading&&!nodes.state.error&&!nodes.state.rows.length" class="empty">{{t("testTools.noNodes")}}</p><div class="pager"><button :disabled="nodes.state.page<=1||nodes.state.loading||busy" @click="nodes.state.page--;nodes.load()">‹</button><span>{{faNumber(nodes.state.page)}} / {{faNumber(nodes.state.pages)}} · {{faNumber(nodes.state.total)}} {{t("testTools.nodes")}}</span><button :disabled="nodes.state.page>=nodes.state.pages||nodes.state.loading||busy" @click="nodes.state.page++;nodes.load()">›</button></div></section>
  <section v-if="node" class="card card-pad lab-section"><div class="page-head"><div><h2>{{node.label}}</h2><p>{{node.protocol}} · {{node.is_enabled?t('testTools.deliveryEnabled'):t('testTools.deliveryDisabled')}}</p></div><RouterLink :to="`/network/${node.id}/cores`" class="btn secondary">{{t("testTools.coreManagement")}}</RouterLink><button class="btn secondary" :disabled="health.state.loading||busy" @click="health.load">{{t("testTools.reloadHealth")}}</button><button v-if="auth.can('network','manage')" class="btn" :disabled="busy" @click="recalculate">{{t("testTools.recalculateHealth")}}</button></div>
    <p v-if="actionError||health.state.error" class="message error" role="alert">{{actionError||health.state.error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><p v-if="health.state.loading">{{t("testTools.healthLoading")}}</p><template v-else-if="nodeHealth"><span class="badge" :class="nodeHealth.status==='healthy'?'success':'warning'">{{healthLabels[nodeHealth.status]??nodeHealth.status}}</span><div class="detail-line"><span>{{t("testTools.samplesSuccessful")}}</span><strong>{{faNumber(nodeHealth.sample_count)}} / {{faNumber(nodeHealth.successful_count)}}</strong></div><div class="detail-line"><span>{{t("testTools.averageLatency")}}</span><strong>{{nodeHealth.average_latency_ms===null?t('testTools.unavailable'):faNumber(nodeHealth.average_latency_ms)+' ms'}}</strong></div><div class="detail-line"><span>{{t("testTools.lastSample")}}</span><strong>{{nodeHealth.last_sample_at?faDate(nodeHealth.last_sample_at):t('testTools.noSample')}}</strong></div><div class="detail-line"><span>{{t("testTools.healthCalculated")}}</span><strong>{{faDate(nodeHealth.checked_at)}}</strong></div></template><p v-else-if="!health.state.error" class="empty">{{t("testTools.noHealth")}}</p>
    <h3>{{t("testTools.corePlacement")}}</h3><form class="toolbar" @submit.prevent="cores.state.page=1;cores.load()"><label class="field"><span>{{t("testTools.searchCores")}}</span><input v-model="coreQ" maxlength="100" :disabled="busy"/></label><button class="btn secondary" :disabled="cores.state.loading||busy">{{t("testTools.search")}}</button><button type="button" class="btn secondary" :disabled="busy" @click="chooseCore(null)">{{t("testTools.allCores")}}</button></form><p v-if="cores.state.error" class="message error" role="alert">{{cores.state.error}}</p><p v-if="cores.state.loading">{{t("testTools.loadingCores")}}</p><div class="inline-actions"><button v-for="row in cores.state.rows" :key="row.id" class="btn secondary" :disabled="busy" :aria-pressed="core?.id===row.id" @click="chooseCore(row)">{{row.label}} · {{row.kind}}</button></div><p v-if="!cores.state.loading&&!cores.state.error&&!cores.state.rows.length">{{t("testTools.noCores")}}</p><div class="pager"><button :disabled="cores.state.page<=1||cores.state.loading||busy" @click="cores.state.page--;cores.load()">‹</button><span>{{faNumber(cores.state.page)}} / {{faNumber(cores.state.pages)}}</span><button :disabled="cores.state.page>=cores.state.pages||cores.state.loading||busy" @click="cores.state.page++;cores.load()">›</button></div>
    <h3>{{t("testTools.configDrafts")}} {{core?t('testTools.onCore',{label:core.label}):''}}</h3><p v-if="configurations.state.error" class="message error" role="alert">{{configurations.state.error}}</p><p v-if="configurations.state.loading">{{t("testTools.loadingDrafts")}}</p><div class="inline-actions"><button v-for="row in configurations.state.rows" :key="row.id" class="btn secondary" :disabled="busy" :aria-pressed="configuration?.id===row.id" @click="configuration=row">{{row.label}} · {{row.protocol}} · {{faNumber(row.listen_port)}}</button></div><p v-if="!configurations.state.loading&&!configurations.state.error&&!configurations.state.rows.length">{{t("testTools.noDrafts")}}</p><div class="pager"><button :disabled="configurations.state.page<=1||configurations.state.loading||busy" @click="configurations.state.page--;configurations.load()">‹</button><span>{{faNumber(configurations.state.page)}} / {{faNumber(configurations.state.pages)}}</span><button :disabled="configurations.state.page>=configurations.state.pages||configurations.state.loading||busy" @click="configurations.state.page++;configurations.load()">›</button></div><RouterLink v-if="configurationLink" :to="configurationLink" class="btn">{{t("testTools.openConfig")}}</RouterLink><p v-if="configuration">{{t("testTools.configNote")}}</p>
  </section>
  <section class="card card-pad lab-section"><h2>{{t("testTools.sourceComparison")}}</h2><form class="toolbar" @submit.prevent="loadQuality"><label class="field"><span>{{t("testTools.sourceNetwork")}}</span><input v-model="source" minlength="2" maxlength="64" required  :placeholder="t('testTools.sourceExample')"/></label><button class="btn secondary" :disabled="qualityLoading||source.trim().length<2">{{t("testTools.compare")}}</button></form><p>{{t("testTools.rankingHint")}}</p><p v-if="qualityError" class="message error" role="alert">{{qualityError}}</p><p v-if="qualityLoading">{{t("testTools.loadingObservations")}}</p><p v-if="recordedSource" >{{t("testTools.showingSource")}} <strong>{{recordedSource}}</strong></p><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("testTools.node")}}</th><th>{{t("testTools.protocol")}}</th><th>{{t("testTools.samplesSuccessful")}}</th><th>{{t("testTools.averageLatency")}}</th><th>{{t("testTools.recordedScore")}}</th></tr></thead><tbody><tr v-for="row in quality" :key="row.node_id"><td>{{row.label}}</td><td>{{row.protocol}}</td><td>{{faNumber(row.sample_count)}} / {{faNumber(row.successful_count)}}</td><td>{{row.average_latency_ms===null?t('testTools.unavailable'):faNumber(row.average_latency_ms)+' ms'}}</td><td>{{row.score===null?t('testTools.insufficientEligible'):faNumber(row.score)}}</td></tr></tbody></table></div><p v-if="recordedSource&&!qualityLoading&&!qualityError&&!quality.length" class="empty">{{t("testTools.noEligible")}}</p></section>
  <section class="card card-pad lab-section"><h2>{{t("testTools.advanced")}}</h2><div class="form-grid"><div><h3>{{t("testTools.coreJson")}}</h3><p>{{t("testTools.coreJsonHint")}}</p></div><div><h3>{{t("testTools.benchmarks")}} <span class="badge warning">{{t("testTools.notAvailable")}}</span></h3><p>{{t("testTools.benchmarksHint")}}</p></div><div><h3>{{t("testTools.loadBalancing")}} <span class="badge warning">{{t("testTools.notAvailable")}}</span></h3><p>{{t("testTools.loadBalancingHint")}}</p><RouterLink to="/host-groups" class="btn secondary">{{t("testTools.deliveryGroups")}}</RouterLink></div></div></section>
</template>
<style scoped>.lab-section{margin-top:20px}h3{margin-top:20px}</style>
